//! Hand-written bindings for Dawn's C API (webgpu.h, generated by the build).
//!
//! Same approach as glfw_bindings.zig: only what we use, field order EXACT
//! like the header (extern structs = C ABI). Pinned to the commit in
//! libs/dawn.commit. Nothing outside render/ includes this (spec §7).

// ── Opaque objects ───────────────────────────────────────────────────────────
pub const WGPUInstance = *opaque {};
pub const WGPUAdapter = *opaque {};
pub const WGPUDevice = *opaque {};
pub const WGPUQueue = *opaque {};
pub const WGPUSurface = *opaque {};
pub const WGPUTexture = *opaque {};
pub const WGPUTextureView = *opaque {};
pub const WGPUBuffer = *opaque {};
pub const WGPUShaderModule = *opaque {};
pub const WGPURenderPipeline = *opaque {};
pub const WGPUBindGroup = *opaque {};
pub const WGPUBindGroupLayout = *opaque {};
pub const WGPUPipelineLayout = *opaque {};
pub const WGPUCommandEncoder = *opaque {};
pub const WGPUCommandBuffer = *opaque {};
pub const WGPURenderPassEncoder = *opaque {};

// ── Scalars ──────────────────────────────────────────────────────────────────
pub const Bool = c_uint;
pub const Flags = u64;

pub const FALSE: Bool = 0;
pub const TRUE: Bool = 1;

// ── Enums (c_uint with the header's values) ──────────────────────────────────
pub const SType_ShaderSourceWGSL: c_uint = 0x00000002;
pub const SType_SurfaceSourceXlibWindow: c_uint = 0x00000006;
pub const SType_SurfaceSourceWaylandSurface: c_uint = 0x00000007;

pub const FeatureLevel_Undefined: c_uint = 0;
pub const InstanceFeatureName_TimedWaitAny: c_uint = 1;
pub const PowerPreference_Undefined: c_uint = 0;
pub const PowerPreference_HighPerformance: c_uint = 2;
pub const BackendType_Undefined: c_uint = 0;
pub const CallbackMode_WaitAnyOnly: c_uint = 1;
pub const CallbackStatus_Success: c_uint = 1;
pub const TextureUsage_RenderAttachment: Flags = 0x10;
pub const TextureUsage_CopyDst: Flags = 0x2;
pub const VertexFormat_Float32x2: c_uint = 0x0000001D;
pub const VertexFormat_Float32x4: c_uint = 0x0000001F;
pub const VertexStepMode_Vertex: c_uint = 1;
pub const PrimitiveTopology_TriangleList: c_uint = 4;
pub const CullMode_None: c_uint = 1;
pub const FrontFace_CCW: c_uint = 1;
pub const IndexFormat_Uint16: c_uint = 1;
pub const LoadOp_Clear: c_uint = 2;
pub const StoreOp_Store: c_uint = 1;
pub const TextureFormat_BGRA8Unorm: c_uint = 0x0000001B;
pub const TextureFormat_BGRA8UnormSrgb: c_uint = 0x0000001C;
pub const PresentMode_Fifo: c_uint = 1;
pub const CompositeAlphaMode_Auto: c_uint = 0;
pub const ColorWriteMask_All: Flags = 0xF;
pub const BufferUsage_Uniform: Flags = 0x40;
pub const BufferUsage_Vertex: Flags = 0x20;
pub const BufferUsage_Index: Flags = 0x10;
pub const BufferUsage_CopyDst: Flags = 0x8;
pub const WaitStatus_Success: c_uint = 1;
pub const MapMode_None: Flags = 0;
pub const Status_Success: c_uint = 1;
pub const SurfaceGetCurrentTextureStatus_SuccessOptimal: c_uint = 1;
pub const SurfaceGetCurrentTextureStatus_SuccessSuboptimal: c_uint = 2;
pub const SurfaceGetCurrentTextureStatus_Timeout: c_uint = 3;
pub const SurfaceGetCurrentTextureStatus_Outdated: c_uint = 4;
pub const SurfaceGetCurrentTextureStatus_Lost: c_uint = 5;
pub const SurfaceGetCurrentTextureStatus_Error: c_uint = 6;
pub const RequestAdapterStatus_Success: c_uint = 1;
pub const ErrorType_NoError: c_uint = 1;

// ── Structs (EXACT header field order) ───────────────────────────────────────
pub const ChainedStruct = extern struct {
    next: ?*ChainedStruct = null,
    sType: c_uint,
};

pub const StringView = extern struct {
    data: ?[*]const u8 = null,
    length: usize = std.math.maxInt(usize), // WGPU_STRLEN

    pub fn from(s: [:0]const u8) StringView {
        return .{ .data = s.ptr, .length = s.len };
    }
};
const std = @import("std");

pub const Color = extern struct {
    r: f64 = 0,
    g: f64 = 0,
    b: f64 = 0,
    a: f64 = 0,
};

pub const Origin3D = extern struct {
    x: u32 = 0,
    y: u32 = 0,
    z: u32 = 0,
};

pub const Extent3D = extern struct {
    width: u32 = 0,
    height: u32 = 0,
    depthOrArrayLayers: u32 = 1,
};

pub const Future = extern struct {
    id: u64 = 0,
};

pub const FutureWaitInfo = extern struct {
    future: Future = .{},
    completed: Bool = FALSE,
};

pub const InstanceDescriptor = extern struct {
    nextInChain: ?*ChainedStruct = null,
    requiredFeatureCount: usize = 0,
    requiredFeatures: ?*const c_uint = null,
    requiredLimits: ?*const anyopaque = null,
};

pub const RequestAdapterOptions = extern struct {
    nextInChain: ?*ChainedStruct = null,
    featureLevel: c_uint = FeatureLevel_Undefined,
    powerPreference: c_uint = PowerPreference_Undefined,
    forceFallbackAdapter: Bool = FALSE,
    backendType: c_uint = BackendType_Undefined,
    compatibleSurface: ?WGPUSurface = null,
};

pub const RequestAdapterCallback = ?*const fn (
    status: c_uint,
    adapter: ?WGPUAdapter,
    message: StringView,
    userdata1: ?*anyopaque,
    userdata2: ?*anyopaque,
) callconv(.c) void;

pub const RequestAdapterCallbackInfo = extern struct {
    nextInChain: ?*ChainedStruct = null,
    mode: c_uint,
    callback: RequestAdapterCallback,
    userdata1: ?*anyopaque = null,
    userdata2: ?*anyopaque = null,
};

pub const RequestDeviceStatus_Success: c_uint = 1;

pub const RequestDeviceCallback = ?*const fn (
    status: c_uint,
    device: ?WGPUDevice,
    message: StringView,
    userdata1: ?*anyopaque,
    userdata2: ?*anyopaque,
) callconv(.c) void;

pub const RequestDeviceCallbackInfo = extern struct {
    nextInChain: ?*ChainedStruct = null,
    mode: c_uint,
    callback: RequestDeviceCallback,
    userdata1: ?*anyopaque = null,
    userdata2: ?*anyopaque = null,
};

pub const UncapturedErrorCallback = ?*const fn (
    device: ?WGPUDevice,
    error_type: c_uint,
    message: StringView,
    userdata1: ?*anyopaque,
    userdata2: ?*anyopaque,
) callconv(.c) void;

pub const DeviceDescriptor = extern struct {
    nextInChain: ?*ChainedStruct = null,
    label: StringView = .{},
    requiredFeatureCount: usize = 0,
    requiredFeatures: ?*const c_uint = null,
    requiredLimits: ?*const anyopaque = null,
    // defaultQueue (WGPUQueueDescriptor: nextInChain + label) inlined:
    defaultQueue_nextInChain: ?*ChainedStruct = null,
    defaultQueue_label: StringView = .{},
    // deviceLostCallbackInfo (WGPUDeviceLostCallbackInfo):
    // nextInChain + mode + callback + userdata1/2
    deviceLost_nextInChain: ?*ChainedStruct = null,
    deviceLost_mode: c_uint = 0,
    deviceLost_callback: ?*const anyopaque = null,
    deviceLost_userdata1: ?*anyopaque = null,
    deviceLost_userdata2: ?*anyopaque = null,
    // uncapturedErrorCallbackInfo (WGPUUncapturedErrorCallbackInfo — has NO
    // `mode` field, unlike deviceLost):
    // nextInChain + callback + userdata1/2
    uncaptured_nextInChain: ?*ChainedStruct = null,
    uncaptured_callback: UncapturedErrorCallback = null,
    uncaptured_userdata1: ?*anyopaque = null,
    uncaptured_userdata2: ?*anyopaque = null,
};

