pub const RenderPipelineDescriptor = extern struct {
    nextInChain: ?*ChainedStruct = null,
    label: StringView = .{},
    layout: ?WGPUPipelineLayout,
    // vertex: VertexState
    vertex_nextInChain: ?*ChainedStruct = null,
    vertex_module: WGPUShaderModule,
    vertex_entryPoint: StringView = .{},
    vertex_constantCount: usize = 0,
    vertex_constants: ?*const anyopaque = null,
    vertex_bufferCount: usize,
    vertex_buffers: ?[*]const VertexBufferLayout,
    // primitive: PrimitiveState
    primitive_nextInChain: ?*ChainedStruct = null,
    primitive_topology: c_uint = PrimitiveTopology_TriangleList,
    primitive_stripIndexFormat: c_uint = 0,
    primitive_frontFace: c_uint = FrontFace_CCW,
    primitive_cullMode: c_uint = CullMode_None,
    primitive_unclippedDepth: Bool = FALSE,
    // depthStencil: nullable pointer
    depthStencil: ?*const anyopaque = null,
    // multisample: MultisampleState
    multisample_nextInChain: ?*ChainedStruct = null,
    multisample_count: u32 = 1,
    multisample_mask: u32 = 0xFFFFFFFF,
    multisample_alphaToCoverageEnabled: Bool = FALSE,
    // fragment: nullable FragmentState
    fragment: ?*const FragmentState,
};

